import { useToolbarItem } from '@dreadnought/react/logic';
import { Button, Toolbar } from '@dreadnought/ui/react';
function Command({ value, label }: { value: string; label: string }) {
  const { itemProps } = useToolbarItem<HTMLButtonElement>({ value });
  return <Button {...itemProps} size='compact'>{label}</Button>;
}
export function Example() {
  return <Toolbar aria-label='Действия документа'><Command value='save' label='Сохранить' /><Command value='copy' label='Копировать' /><Command value='download' label='Скачать' /></Toolbar>;
}

import { Toolbar, Input, Select, Button } from '@dreadnought/ui/react';
